import type { Plugin } from "../../kernel/types";

const plugin: Plugin = {
  id: "calculator",
  name: "Calculator",
  version: "1.0.0",
  onLoad(ctx) {
    ctx.register({
      kind: "tool",
      tool: {
        name: "sum_values",
        version: "1.0.0",
        description: "对给定的数字数组求和，返回总和。",
        permissions: [],
        sideEffect: "none",
        parameters: {
          type: "object",
          properties: {
            numbers: {
              type: "array",
              items: { type: "number" },
              description: "要求和的数字数组",
            },
          },
          required: ["numbers"],
        },
        outputSchema: {
          type: "object",
          properties: {
            sum: { type: "number", description: "数组元素之和" },
          },
          required: ["sum"],
        },
        async handler(args: { numbers: number[] }, tctx) {
          const numbers = Array.isArray(args?.numbers) ? args.numbers : [];
          const sum = numbers.reduce((acc, n) => acc + Number(n), 0);
          return { ok: true, data: { sum } };
        },
      },
    });
  },
};

export default plugin;

